"""Public integration disclosures; no credentials or runtime data are read."""
import re

def update_cloud_disclosures(home, privacy, terms, four):
    def p(*texts): return '<p>'+four(*texts)+'</p>'
    def h(anchor,*texts): return '<h2 id="'+anchor+'">'+four(*texts)+'</h2>'
    public_intro=p(
      'Each visitor has a simulated café in this browser profile. Optional Gmail connects your own Google account to save an approved demo draft. Optional Runpod uses your own endpoint and key for one explicitly approved paid review. No owner keys are shared. The local installed workbench remains separate.',
      '每位访客在当前浏览器配置中使用模拟门店。可选 Gmail 连接你自己的 Google 账号，保存已批准的模拟草稿；可选 Runpod 使用你自己的端点和 Key，执行一次明确批准的付费复核。不共用站长密钥，本机安装版保持独立。',
      'Setiap pelawat mempunyai kafe simulasi dalam profil pelayar ini. Gmail pilihan menyambungkan akaun Google anda untuk menyimpan draf demo yang diluluskan. Runpod pilihan menggunakan endpoint dan kunci anda untuk satu semakan berbayar yang diluluskan secara nyata. Tiada kunci pemilik dikongsi. Aplikasi setempat kekal berasingan.',
      'Cada visitante tiene una cafetería simulada en este perfil del navegador. Gmail opcional conecta tu cuenta para guardar un borrador aprobado. Runpod opcional usa tu endpoint y clave para una revisión de pago autorizada expresamente. No se comparten claves del propietario. La aplicación local sigue siendo independiente.')
    home=re.sub(r'<section class="data-section">.*?</section>', '<section class="data-section"><div class="wrap section">'+h('connections','Your accounts. Your choice.','你的账号，由你决定。','Akaun anda. Pilihan anda.','Tus cuentas. Tu decisión.')+public_intro+'<a class="text-link" href="/privacy/">'+four('Read the privacy policy →','阅读隐私政策 →','Baca dasar privasi →','Lee la política de privacidad →')+'</a></div></section>',home,flags=re.S)
    home=re.sub(r'<article><span class="step-num">04</span>.*?</article>', '<article><span class="step-num">04</span><h3>'+four('Prepare supplier drafts','生成供应商草稿','Sediakan draf pembekal','Prepara borradores')+'</h3>'+p('Download simulated drafts, or connect your own Gmail and review a draft before saving. This app does not send email.','下载模拟草稿，或连接自己的 Gmail，核对后保存草稿。此应用不发送邮件。','Muat turun draf simulasi atau sambungkan Gmail anda dan semak sebelum menyimpan. Aplikasi ini tidak menghantar e-mel.','Descarga borradores simulados o conecta tu Gmail y revisa antes de guardar. La aplicación no envía correos.')+'</article>',home,flags=re.S)
    # Retain local-application details while replacing outdated public-only claims.
    privacy=re.sub(r'<p class="doc-intro">.*?</p>', '<p class="doc-intro">'+four('How the public demo and separate local app handle your data.','公开演示与独立本机应用如何处理资料。','Cara demo awam dan aplikasi setempat mengendalikan data.','Cómo tratan tus datos la demo pública y la aplicación local.')+'</p>',privacy,flags=re.S)
    privacy=re.sub(r'<p\b[^>]*>.*?</p>',lambda m: '<p>'+four('The public site provides an independent browser café simulation without an application account. Simulated stock, approvals, drafts and audit history remain in localStorage in this browser profile; shared profiles share that state. Reset demo clears simulation data, not downloads, history or provider records. It does not connect to the separate local owner workbench.','公开网站提供无需应用账户的独立浏览器门店模拟。模拟库存、审批、草稿和日志保存在当前浏览器配置的 localStorage，共用配置的使用者共享数据。重置清除模拟资料，不删除下载、浏览历史或服务商记录；不会连接独立本机老板工作台。','Laman awam menyediakan simulasi kafe tanpa akaun aplikasi. Stok, kelulusan, draf dan sejarah simulasi disimpan dalam localStorage profil pelayar; profil dikongsi berkongsi data. Tetapan semula tidak memadam muat turun, sejarah atau rekod penyedia. Ia tidak menyambung ke meja kerja pemilik setempat.','El sitio ofrece una simulación sin cuenta de aplicación. Inventario, aprobaciones, borradores e historial simulados quedan en localStorage de este perfil; los perfiles compartidos comparten esos datos. Restablecer no borra descargas, historial ni registros de proveedores. No conecta con el panel local del propietario.')+'</p>' if 'The public website provides project information' in re.sub('<[^>]+>',' ',m.group(0)) else m.group(0),privacy,flags=re.S)
    privacy=re.sub(r'<p\b[^>]*>.*?</p>',lambda m:'<p>'+four('Weather is requested directly from Open-Meteo for fixed Kuala Lumpur coordinates and the selected date. Your actual location is not used. Weather simulations are labelled. Hosting and external providers may process ordinary network request information. The app adds no advertising trackers. Keep private business information out of the simulation.','天气以固定吉隆坡坐标和所选日期直接请求 Open-Meteo，不读取实际位置；模拟天气会标注。托管和第三方服务可能处理常规网络请求资料。应用不添加广告追踪器，请勿在模拟中填写机密业务资料。','Cuaca diminta terus daripada Open-Meteo bagi koordinat tetap Kuala Lumpur dan tarikh pilihan, tanpa lokasi sebenar anda. Simulasi dilabel. Pengehos dan penyedia boleh memproses maklumat rangkaian biasa. Tiada penjejak iklan ditambah. Jangan masukkan maklumat perniagaan sulit.','El clima se consulta directamente en Open-Meteo con coordenadas fijas de Kuala Lumpur y la fecha elegida, sin usar tu ubicación real. Las simulaciones se identifican. Los proveedores pueden procesar información habitual de red. No añadimos rastreadores publicitarios. No introduzcas datos comerciales confidenciales.')+'</p>' if 'The public demo requests Kuala Lumpur weather' in re.sub('<[^>]+>',' ',m.group(0)) else m.group(0),privacy,flags=re.S)
    gmail=h('public-gmail','Public Gmail connection','公开版 Gmail 连接','Sambungan Gmail awam','Conexión pública de Gmail')+p(
      'Gmail is optional. Google Identity Services asks for openid, email and gmail.compose. Google defines gmail.compose as managing drafts and sending email; this implementation only creates drafts and has no send operation. The account identity identifies the destination mailbox. No inbox or existing message bodies are imported. The Google app is currently unverified; Google may display a warning and restrict authorization to 100 users until approval.',
      'Gmail 为可选连接。Google Identity Services 请求 openid、email 和 gmail.compose，用账号身份确认目标邮箱。Google 的 gmail.compose 权限包含管理草稿和发送邮件；当前实现只有创建草稿，没有发送操作，不导入收件箱或已有邮件正文。应用尚未经 Google 验证，Google 可能显示提示，并在审核通过前将授权人数限制为 100 人。',
      'Gmail ialah pilihan. Google Identity Services meminta openid, email dan gmail.compose untuk mengenal pasti peti mel. Skop gmail.compose boleh mengurus draf dan menghantar e-mel; pelaksanaan ini hanya mencipta draf tanpa operasi penghantaran. Peti masuk atau kandungan mesej sedia ada tidak diimport. Aplikasi belum disahkan Google; amaran dan had 100 pengguna mungkin dikenakan sebelum kelulusan.',
      'Gmail es opcional. Google Identity Services solicita openid, email y gmail.compose para identificar el buzón. gmail.compose permite gestionar borradores y enviar correos; esta implementación solo crea borradores y no tiene una operación de envío. No importa la bandeja de entrada ni mensajes existentes. La aplicación no está verificada; Google puede mostrar avisos y limitar la autorización a 100 usuarios hasta aprobarla.')+p(
      'The browser sends your selected approved demo recipient, subject and body directly to Google only after a separate preview confirmation. Tokens, account identity, draft IDs and duplicate locks stay in tab memory, not this site’s backend or browser storage. No refresh token is requested; when access expires, reconnect using Google. Closing or reloading clears that session and its duplicate locks. An uncertain save blocks another attempt in that tab; check Gmail before reconnecting or reloading.',
      '单独预览确认后，浏览器才将所选已批准模拟收件人、标题和正文直接提交 Google。令牌、账号身份、草稿 ID 和防重复锁仅保留在标签页内存，不写入本站后端或浏览器存储。不请求刷新令牌；访问过期后通过 Google 重新连接。关闭或刷新会清除会话和防重复锁；保存结果不确定时本标签页会阻止再次提交，重新连接或刷新前请先检查 Gmail。',
      'Selepas pengesahan pratonton berasingan, pelayar menghantar penerima demo, subjek dan isi yang diluluskan terus kepada Google. Token, identiti, ID draf dan kunci pendua hanya berada dalam memori tab, bukan backend atau storan pelayar. Tiada refresh token diminta; sambung semula apabila akses tamat. Tutup atau muat semula memadam sesi dan kunci. Jika hasil tidak pasti, semak Gmail sebelum menyambung atau memuat semula.',
      'Tras confirmar una vista previa, el navegador envía directamente a Google destinatario simulado, asunto y cuerpo aprobados. Tokens, identidad, IDs y bloqueos de duplicados quedan solo en memoria de la pestaña, no en el servidor ni almacenamiento del navegador. No se solicita refresh token; reconecta cuando caduque el acceso. Cerrar o recargar borra sesión y bloqueos. Un resultado incierto bloquea otro intento en esa pestaña; revisa Gmail antes de reconectar o recargar.')
    runpod=h('public-runpod','Visitor-owned Runpod review','访客自备 Runpod 复核','Semakan Runpod milik pelawat','Revisión con tu Runpod')+p(
      'You provide your endpoint, model and API key. The key passes over HTTPS through the same-site Netlify function to Runpod for the approved request; it is not saved by application code. Only synthetic SKU forecasts, target date, temperature, rainfall and holiday flag are sent. Gmail information, supplier contacts and email contents are never included or used for AI training. The preview shows the exact payload. Every paid submission requires an explicit click. Results advise; local quantities and human approval remain authoritative.',
      '你自行提供端点、模型和 API Key。批准调用时，Key 通过 HTTPS 经本站 Netlify 函数转给 Runpod，应用代码不保存 Key。只发送模拟商品预测、目标日期、气温、降雨和假日标记，不包含 Gmail 资料、供应商联系信息或邮件正文，也不将其用于 AI 训练。预览展示准确载荷，每次付费提交都需明确点击。结果仅供参考，采购计算和人工审批保持有效。',
      'Anda menyediakan endpoint, model dan API key. Bagi permintaan diluluskan, kunci melalui HTTPS dan fungsi Netlify laman ini ke Runpod; kod aplikasi tidak menyimpannya. Hanya ramalan SKU simulasi, tarikh, suhu, hujan dan tanda cuti dihantar. Maklumat Gmail, pembekal dan isi e-mel tidak disertakan atau digunakan melatih AI. Pratonton menunjukkan payload tepat; setiap penghantaran berbayar memerlukan klik nyata. Hasil hanya nasihat; kiraan setempat dan kelulusan manusia kekal berkuasa.',
      'Aportas endpoint, modelo y API key. En la solicitud aprobada, la clave pasa por HTTPS y la función Netlify del sitio a Runpod; el código no la guarda. Solo se envían previsiones simuladas por SKU, fecha, temperatura, lluvia y festivo. Nunca se incluyen datos Gmail, contactos de proveedores ni correos, ni se usan para entrenar IA. La vista previa muestra el contenido exacto y cada envío de pago exige un clic. El resultado es orientativo; cálculo local y aprobación humana siguen siendo la referencia.')+p(
      'Limits include 1024 output tokens, 10 seconds of active inference, a five-minute job lifetime and durable site-wide operation caps. These do not guarantee a price or completion. No paid auto-retries or automatic polling occur. A manual status check retrieves the same job without resubmitting. Durable storage retains hashes, counters, nonces, states and bounded job IDs, never keys or raw forecasts. Ambiguous results keep the original submission locked, including after reload.',
      '限制包括最多 1024 输出 token、10 秒实际推理、5 分钟任务总寿命及全站持久化调用上限；这些不能保证费用或完成时间。没有付费自动重试或自动轮询；手动查状态只查询同一任务，不重新提交。持久存储只保留哈希、计数、随机标识、状态及受限任务 ID，不保存 Key 或原始预测。结果不确定时原提交保持锁定，刷新后仍有效。',
      'Had termasuk 1024 token output, 10 saat inferens aktif, hayat tugas lima minit dan had operasi seluruh laman. Ini tidak menjamin harga atau kejayaan. Tiada cubaan semula berbayar atau polling automatik. Semakan manual membaca tugas sama tanpa penghantaran semula. Storan kekal hanya menyimpan hash, kiraan, nonce, status dan ID tugas terhad, bukan kunci atau ramalan mentah. Hasil tidak pasti kekal dikunci selepas muat semula.',
      'Los límites incluyen 1024 tokens de salida, 10 segundos de inferencia activa, cinco minutos de vida del trabajo y topes persistentes del sitio. No garantizan precio ni finalización. No hay reintentos de pago ni sondeo automático. La consulta manual recupera el mismo trabajo sin reenviarlo. Se conservan hashes, contadores, nonces, estados e IDs acotados, nunca claves ni previsiones completas. Los envíos inciertos siguen bloqueados tras recargar.')
    disconnect=h('public-disconnect','Disconnecting your public session','断开公开版会话','Memutuskan sesi awam','Desconectar la sesión pública')+p(
      'Disconnect forgets the tab’s Gmail connection. Revoke also asks Google to revoke access; failures are reported and you can use Google Account connections. Neither action deletes existing Gmail drafts. Clear Runpod credentials or close the tab to forget its key. These public-session rules differ from the local installed app’s DPAPI-protected refresh tokens described below.',
      '断开会清除标签页的 Gmail 连接；撤销还会请求 Google 撤销授权，失败会提示，也可在 Google 账户第三方连接中处理。两者都不删除 Gmail 已有草稿。清除 Runpod 凭据或关闭标签页可忘记 Key。公开版会话规则与下述本机安装版的 DPAPI 保护刷新令牌不同。',
      'Putuskan melupakan sambungan Gmail tab. Batalkan juga meminta Google menarik akses; kegagalan dipaparkan dan boleh diurus melalui sambungan Akaun Google. Draf sedia ada tidak dipadam. Kosongkan kelayakan Runpod atau tutup tab untuk melupakan kunci. Peraturan ini berbeza daripada refresh token terlindung DPAPI aplikasi setempat di bawah.',
      'Desconectar olvida la conexión Gmail de la pestaña. Revocar también solicita retirar el acceso a Google; se informan fallos y puedes usar las conexiones de tu cuenta. Ninguna acción borra borradores existentes. Borra las credenciales Runpod o cierra la pestaña para olvidar la clave. Estas reglas difieren de los refresh tokens protegidos por DPAPI de la aplicación local descrita abajo.')
    privacy=privacy.replace('<h2 id="local">',gmail+runpod+disconnect+'<h2 id="local">',1)
    # Old Chinese summary predates public cloud support; retain only the Limited Use section above.
    privacy=re.sub(r'<div class="notice" lang="zh-CN">.*?</div>','',privacy,flags=re.S)
    privacy=privacy.replace('22 October 2026','23 October 2026')
    terms+=h('public-cloud','Optional public cloud integrations','可选公开云端连接','Integrasi awan awam pilihan','Integraciones públicas opcionales')+public_intro+p('Saving a Gmail draft is not sending email or placing an order. Runpod may charge your account even if a job queues or fails; inspect its own usage and budget. Preview before approving. The site does not provide an uptime, model accuracy, delivery or price guarantee. Google authorization remains subject to its unverified-app limits.','保存 Gmail 草稿不等于发送邮件或下单。Runpod 即使排队或失败也可能计费，请检查该平台用量和预算，批准前先预览。网站不保证可用性、模型准确性、送达或价格；Google 授权仍受未验证应用限制。','Menyimpan draf Gmail bukan penghantaran e-mel atau pesanan. Runpod mungkin mengenakan caj walaupun tugas beratur atau gagal; semak penggunaan dan bajetnya. Pratonton sebelum meluluskan. Tiada jaminan masa operasi, ketepatan, penghantaran atau harga. Kebenaran Google tertakluk pada had aplikasi belum disahkan.','Guardar un borrador no envía correo ni hace un pedido. Runpod puede cobrar incluso por trabajos en cola o fallidos; revisa su consumo y presupuesto. Previsualiza antes de aprobar. No se garantiza disponibilidad, precisión, entrega ni precio. La autorización Google sigue sujeta a límites de aplicaciones sin verificar.')
    terms=terms.replace('22 October 2026','23 October 2026')
    return home,privacy,terms
